  "codebook": {
    "definition": "Credit-claiming refers to statements or announcements in which a senator claims personal or collective responsibility for securing a desirable government outcome, policy, or benefit for their constituents, their state, or the general public.",
    "clarification": "To categorize a text as credit-claiming (1), look for indicators such as: (a) announcements of federal grants, projects, or earmarks awarded to the senator's state; (b) mentions of having sponsored, authored, or co-sponsored a bill, amendment, or resolution; (c) accounts of successful personal or committee interventions (like writing letters, requesting audits, or hosting roundtables) that influenced agency actions; or (d) references to awards and recognition received for the senator's legislative records.",
    "positive_examples": [
      {
        "document_id": "1862",
        "explanation": "Senators Baucus and Tester explicitly claim credit for securing $12.5 million for military projects in Butte, stating they 'delivered on their promise' and 'went to bat for these dollars.'"
      },
      {
        "document_id": "89",
        "explanation": "Senator Dorgan explicitly claims credit for authoring the legislation signed into law that created the National Center designation for Bismarck State College."
      }
    ],
    "negative_clarification": "Do not classify a text as credit-claiming (0) if the senator is merely: (a) taking a position of support or opposition on a policy or nominee (position-taking); (b) criticizing or offering general oversight of the executive branch or political opponents; (c) making ceremonial, condolence, or historical commemoration statements; or (d) advocating or proposing an action without showing a completed positive result.",
    "negative_examples": [
      {
        "document_id": "656",
        "explanation": "Senator Kerry's press release focuses entirely on criticizing the Bush administration's port security failures. It is purely position-taking and oversight criticism rather than credit-claiming."
